 			data[1], data[2], data[3], data[4], data[5]);
 	else {
 		fprintf(stderr, "%s: Read from persist memory failed : Programming default"
-			" BD ADDR\n");
+			" BD ADDR\n", __func__);
 		close(fd);
 		return -1;
 	}
@@ -962,13 +962,14 @@ int rome_get_tlv_file(char *file_path, unsigned char baud_rate)
 	FILE * pFile;
